  'rs.facets_help': '核取方塊列出最常見的值(「排除」讓使用者改為將其篩除)。範圍和「從/到」需要數字或日期欄:範圍寫作 `from..to = label`,以 `;` 分隔,開放的一端留空(`..1000`、`2020-01-01..`);範圍包含起點,不包含終點。星級評分提供「4 星以上」等選項(最多 5;JSON 中的 `"max"` 可變更)。',
