  'rs.chart_help': '第一欄是標籤;其後的每個數值欄是一個數列(最多 8 個)。甘特圖讀取 `label, start, end`(日期或時間戳記;結束為空表示里程碑)以及選用欄 `progress`(0 到 100)、`task_id` 和 `depends_on`(工作等待的 id,例如 `3,4`)。',
  'rs.map_help': '每列是位於 `lat`、`lng`(或格式為 "lat,lng" 的 `location`)的一個標記,彈出框中顯示 `title` 和 `body`;`geojson` 欄繪製線和區域(安裝 PostGIS 後,WGS 84 中的 `geometry` 或 `geography` 欄也可以)。熱度圖依 `weight` 欄為每個地點加權。',
