  'rm.response_as': '以 {as} 身分傳送 {request}',
  'rm.try_intro': '將要求傳送到真實端點:PUT、POST 或 DELETE 會變更資料。在{as}中選擇帳戶時,會像「應用程式 › REST API」那樣為其簽發短期權杖;不選則可以看到無權杖呼叫端得到的結果。',
  'rm.intro': 'RESTful 服務模組:模組是應用程式的一個基本路徑,其範本是帶 `:parameters` 的 URI,每個範本按方法有處理常式及其來源:集合查詢、單列、SQL、PL/pgSQL 區塊或媒體資源。處理常式以應用程式的資料庫角色執行,呼叫端為 `meta.app_user()`,因此其授權和列層級安全性適用;參數是繫結的,絕不會貼進 SQL。每個模組都有 OpenAPI 文件。模組屬於其應用程式:隨應用程式匯出一起移動(也在「共用元件 › RESTful 服務」中)。',
  'rm.source_help': '繫結變數,大寫:路徑參數({params})、查詢參數和 JSON 本文欄位;`:BODY` 是整個本文;`:APP_USER` 是呼叫端。值是繫結的,絕不會貼進 SQL。PL/pgSQL:一個區塊(`declare … begin … end` 或陳述式),以 `perform meta.rest_reply(jsonb_build_object(…), 201)` 回應。媒體:傳回 `content_type`、`content` 以及選用 `filename` 的查詢。',
  'rm.params_help': '每行一個:`name query|body|header [{types}] [required] [description]`。它們會進入 OpenAPI 文件和「試試看」表單;缺少必要參數時傳回 400。header 參數讀取以其名稱(_ 換成 -)命名的請求標頭(`x_request_id` 讀取 `X-Request-Id`)。',
  'rm.e.params_line': '參數,第 {n} 行:請寫 "name query", "name body" 或 "name header",然後可選寫類型({types})、"required" 和描述。',
